// Targeted almost-regular parent atlas and parent-only regular reroot trace.
// Canonicalization is restricted at compile time to orders 6,8,10.
#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;
uint64_t checks=0,canonical_calls=0,candidates=0,refinements=0;
void need(bool b,const char*s){++checks;if(!b)throw runtime_error(s);}
int bits(unsigned a){return __builtin_popcount(a);}
uint64_t fact(int n){uint64_t x=1;for(int i=2;i<=n;++i)x*=i;return x;}
template<size_t N>using Rows=array<unsigned,N>;
template<size_t N>using Perm=array<unsigned,N>;
template<size_t N>unsigned image(unsigned m,const Perm<N>&p){unsigned x=0;for(unsigned i=0;i<N;++i)if(m>>i&1)x|=1u<<p[i];return x;}
template<size_t N>void valid_rows(const Rows<N>&r){for(unsigned i=0;i<N;++i){need(r[i]<(1u<<N)&&!(r[i]>>i&1),"row width and loop");for(unsigned j=0;j<i;++j)need(((r[i]>>j&1)+(r[j]>>i&1))==1,"tournament arcs");}}
template<size_t N>void valid_group(const Rows<N>&r,const vector<Perm<N>>&g){Perm<N>id{};iota(id.begin(),id.end(),0);set<Perm<N>>s(g.begin(),g.end());need(s.size()==g.size()&&s.count(id),"distinct group with identity");for(auto p:g){auto q=p;sort(q.begin(),q.end());need(q==id,"permutation");for(unsigned i=0;i<N;++i)need(image(r[i],p)==r[p[i]],"action preserves every arc");for(auto h:g){Perm<N>z{};for(unsigned i=0;i<N;++i)z[i]=p[h[i]];need(s.count(z),"group closure");}}}
template<size_t N>vector<vector<unsigned>> cells(const Rows<N>&r){++refinements;array<unsigned,N>c{},next{},order{};for(unsigned i=0;i<N;++i){c[i]=bits(r[i]);order[i]=i;}for(;;){array<unsigned,N>masks{};for(unsigned i=0;i<N;++i)masks[c[i]]|=1u<<i;unsigned old=0;for(auto m:masks)old+=(m!=0);array<array<unsigned,N+1>,N>sig{};for(unsigned i=0;i<N;++i){sig[i][0]=c[i];for(unsigned j=0;j<N;++j)sig[i][j+1]=bits(r[i]&masks[j]);}sort(order.begin(),order.end(),[&](unsigned a,unsigned b){return sig[a]<sig[b];});unsigned nc=0;next[order[0]]=0;for(unsigned j=1;j<N;++j){nc+=(sig[order[j]]!=sig[order[j-1]]);next[order[j]]=nc;}c=next;if(nc+1==old){vector<vector<unsigned>>out(nc+1);for(unsigned i=0;i<N;++i)out[c[i]].push_back(i);return out;}}}
template<size_t N>bool almost(const Rows<N>&r){unsigned lo=0,hi=0;for(auto a:r){lo+=bits(a)==int(N/2-1);hi+=bits(a)==int(N/2);}return lo==N/2&&hi==N/2;}
template<size_t N>struct Normal{Rows<N>rows{};vector<Perm<N>>witnesses;unsigned rotations=0;};
template<size_t N>Normal<N> normal(const Rows<N>&r){static_assert(N==6||N==8||N==10,"parent-only normalizer");++canonical_calls;need(almost(r),"normalizer only almost-regular even parents");auto cc=cells(r);vector<vector<unsigned>>cycles;unsigned bound=1;for(auto cell:cc){unsigned k=cell.size();need(k==1||k==3||k==5,"stable cells size one three five");unsigned mask=0;for(auto v:cell)mask|=1u<<v;for(auto v:cell)need(bits(r[v]&mask)==int((k-1)/2),"cell internal regularity");vector<unsigned>cyc;if(k==1)cyc=cell;else{unsigned v=cell[0];for(unsigned i=0;i<k;++i){need(find(cyc.begin(),cyc.end(),v)==cyc.end(),"intrinsic successor simple cycle");cyc.push_back(v);unsigned next=N;for(auto w:cell)if(r[v]>>w&1){if(k==3||bits(r[w]&r[v]&mask)==1){need(next==N,"intrinsic successor unique");next=w;}}need(next<N,"intrinsic successor exists");v=next;}need(v==cyc[0],"intrinsic successor closes");for(unsigned i=0;i<k;++i)for(unsigned j=1;j<k;++j)need(bool(r[cyc[i]]>>cyc[(i+j)%k]&1)==(j<=k/2),"cell is consecutive cyclic tournament");}cycles.push_back(cyc);bound*=k;}need(bound<=25,"at most twenty-five full-matrix rotation candidates");Normal<N>out;out.rotations=bound;Perm<N>p{};bool first=true;function<void(unsigned,unsigned)>visit=[&](unsigned k,unsigned offset){if(k==cycles.size()){++candidates;Rows<N>val{};for(unsigned i=0;i<N;++i)val[p[i]]=image(r[i],p);if(first||val<out.rows){out.rows=val;out.witnesses.clear();first=false;}if(val==out.rows)out.witnesses.push_back(p);return;}auto cyc=cycles[k];for(unsigned shift=0;shift<cyc.size();++shift){for(unsigned j=0;j<cyc.size();++j)p[cyc[(j+shift)%cyc.size()]]=offset+j;visit(k+1,offset+cyc.size());}};visit(0,0);need(!out.witnesses.empty(),"normal form witness");return out;}
template<size_t N>vector<Perm<N>> normal_group(const Normal<N>&can){Perm<N>inv{};for(unsigned i=0;i<N;++i)inv[can.witnesses[0][i]]=i;vector<Perm<N>>g;for(auto w:can.witnesses){Perm<N>p{};for(unsigned i=0;i<N;++i)p[i]=w[inv[i]];g.push_back(p);}sort(g.begin(),g.end());return g;}
template<size_t N>Rows<N+1> extend(const Rows<N>&r,unsigned mask){Rows<N+1>x{};for(unsigned i=0;i<N;++i)x[i]=r[i]|((mask>>i&1)<<N);x[N]=((1u<<N)-1)^mask;return x;}
template<size_t N>Rows<N-1> erase_root(const Rows<N>&r,unsigned root){Rows<N-1>x{};unsigned a=0;for(unsigned i=0;i<N;++i)if(i!=root){unsigned b=0;for(unsigned j=0;j<N;++j)if(j!=root){if(r[i]>>j&1)x[a]|=1u<<b;++b;}++a;}return x;}
template<size_t N>unsigned orbit_count(const vector<Perm<N>>&g){unsigned seen=0,n=0;for(unsigned i=0;i<N;++i)if(!(seen>>i&1)){++n;for(auto p:g)seen|=1u<<p[i];}need(seen==(1u<<N)-1,"vertex orbit coverage");return n;}
void hist(ostream&o,const map<unsigned,uint64_t>&h){o<<'[';bool f=true;for(auto x:h){if(!f)o<<',';f=false;o<<'['<<x.first<<','<<x.second<<']';}o<<']';}
template<size_t M>void run(const string&input,const string&prefix,bool cost_only){constexpr unsigned N=M+1,K=M+2;struct Parent{Rows<M>r;vector<Perm<M>>g;};ifstream in(input);need(bool(in),"input opened");unsigned count;in>>count;need(bool(in)&&count>0&&count<1000000,"bounded input header");vector<Parent>src(count);uint64_t inputmass=0;set<Rows<M>>inputrows;for(auto &a:src){for(auto &x:a.r)in>>x;unsigned ng;in>>ng;need(bool(in)&&ng>0&&ng<=fact(M),"input group bound");a.g.resize(ng);for(auto &g:a.g)for(auto &v:g)in>>v;need(bool(in),"complete input record");valid_rows(a.r);valid_group(a.r,a.g);need(fact(M)%ng==0,"input group factorial divisor");inputmass+=fact(M)/ng;need(inputrows.insert(a.r).second,"literal distinct input rows");}string trailing;in>>trailing;need(trailing.empty(),"no trailing input");need(inputmass==(1ull<<(M*(M-1)/2)),"complete input labelled mass");
 struct Dest{Rows<N>r;vector<Perm<N>>g;uint64_t pointed_sources=0;};map<Rows<N>,Dest>unique;uint64_t eligibleparents=0,rawmasks=0,pointed=0,source_mass=0;map<unsigned,uint64_t>rot_hist,aut_hist;
 for(auto a:src){unsigned must=0,optional=0;bool eligible=true;for(unsigned v=0;v<M;++v){int d=bits(a.r[v]);if(d<int(N/2-2)||d>int(N/2))eligible=false;else if(d==int(N/2-2))must|=1u<<v;else if(d==int(N/2-1))optional|=1u<<v;}if(!eligible)continue;++eligibleparents;set<unsigned>masks;for(unsigned sub=optional;;sub=(sub-1)&optional){unsigned mask=must|sub;if(bits(mask)==int(N/2-1)||bits(mask)==int(N/2))masks.insert(mask);if(sub==0)break;}rawmasks+=masks.size();source_mass+=masks.size()*(fact(M)/a.g.size());if(cost_only)continue;set<unsigned>seen;for(auto mask:masks){if(seen.count(mask))continue;set<unsigned>orb;unsigned stabilizer=0;for(auto g:a.g){unsigned y=image(mask,g);need(masks.count(y),"eligible masks invariant under source actions");orb.insert(y);stabilizer+=(y==mask);}need(*orb.begin()==mask,"least eligible subset representative");for(auto y:orb)need(seen.insert(y).second,"disjoint eligible subset orbits");need(orb.size()*stabilizer==a.g.size(),"subset orbit stabilizer");++pointed;auto r=extend(a.r,mask);need(almost(r),"generated parent almost regular");auto can=normal(r);++rot_hist[can.rotations];auto found=unique.find(can.rows);if(found==unique.end()){Dest z{can.rows,normal_group(can),0};valid_group(z.r,z.g);found=unique.emplace(z.r,z).first;}else need(found->second.g.size()==can.witnesses.size(),"normal witness count invariant");++found->second.pointed_sources;}need(seen.size()==masks.size(),"eligible source subset coverage");}
 cerr<<"order="<<K<<" eligible parents="<<eligibleparents<<" raw masks="<<rawmasks<<" pointed="<<pointed<<" normalized parents="<<unique.size()<<"\n";
 if(cost_only){cout<<"{\"source_order\":"<<M<<",\"eligible_parents\":"<<eligibleparents<<",\"raw_masks\":"<<rawmasks<<",\"source_labelled_almost_regular_mass\":"<<source_mass<<"}\n";return;}
 need(unique.size()<200000,"targeted parent atlas cost ceiling");vector<Dest>atlas;map<Rows<N>,unsigned>index;uint64_t atlas_mass=0;for(auto x:unique){index[x.first]=atlas.size();atlas.push_back(x.second);auto &a=atlas.back();need(a.pointed_sources==orbit_count(a.g),"all pointed source states equal parent vertex orbits");need(fact(N)%a.g.size()==0,"parent group factorial divisor");atlas_mass+=fact(N)/a.g.size();++aut_hist[a.g.size()];}need(atlas_mass==source_mass,"complete targeted parent labelled orbit mass");
 vector<map<unsigned,unsigned>>D(atlas.size());vector<unsigned>converse(atlas.size());uint64_t trace=0;map<unsigned,uint64_t>trace_rot_hist;for(unsigned i=0;i<atlas.size();++i){auto &a=atlas[i];unsigned mask=0;for(unsigned v=0;v<N;++v)if(bits(a.r[v])==int(N/2-1))mask|=1u<<v;auto child=extend(a.r,mask);for(auto x:child)need(bits(x)==N/2,"unique extension regular");for(unsigned v=0;v<K;++v){auto can=normal(erase_root(child,v));++trace_rot_hist[can.rotations];auto it=index.find(can.rows);need(it!=index.end(),"every reroot in targeted parent atlas");++D[i][it->second];}need(D[i].count(i),"own root returns own state");trace+=D[i][i];Rows<N>rev{};for(unsigned v=0;v<N;++v)rev[v]=((1u<<N)-1)^a.r[v]^(1u<<v);auto can=normal(rev);auto it=index.find(can.rows);need(it!=index.end(),"converse parent in atlas");converse[i]=it->second;}
 vector<int>component(atlas.size(),-1);vector<vector<unsigned>>components;vector<unsigned>grouporders;map<unsigned,uint64_t>error_hist,child_aut_hist;map<vector<unsigned>,uint64_t>orbit_hist;uint64_t child_mass=0,totalerror=0;for(unsigned i=0;i<atlas.size();++i)if(component[i]<0){vector<unsigned>c,orbits;unsigned gorder=0,sum=0,diag=0;for(auto x:D[i]){unsigned j=x.first;need(component[j]<0,"components disjoint");need(D[j]==D[i],"reroot rows identical within component");component[j]=components.size();c.push_back(j);orbits.push_back(x.second);sum+=x.second;diag+=D[j].at(j);unsigned g=D[j].at(j)*atlas[j].g.size();if(!gorder)gorder=g;need(gorder==g,"full child group order from every stabilizer");need(g%x.second==0,"child group divisible by vertex orbit");}need(sum==K&&diag==K,"component row sum and trace equal target order");sort(orbits.begin(),orbits.end());need(fact(K)%gorder==0,"child group factorial divisor");child_mass+=fact(K)/gorder;unsigned e=K*(c.size()-1);need(e%(2*K)==0,"positive regular error even target multiple");++error_hist[e];++child_aut_hist[gorder];++orbit_hist[orbits];totalerror+=e;components.push_back(c);grouporders.push_back(gorder);}
 need(trace==K*components.size(),"trace divided by target order equals components");need(totalerror==K*(atlas.size()-components.size()),"regular correction identity");need(child_mass==atlas_mass,"regular labelled mass equals almost-regular parent mass");uint64_t selfparents=0,selfchildren=0;map<unsigned,uint64_t>self_error_hist;for(unsigned i=0;i<atlas.size();++i){need(converse[converse[i]]==i,"converse involution on parents");selfparents+=(converse[i]==i);map<unsigned,unsigned>mapped;for(auto x:D[i])mapped[converse[x.first]]=x.second;need(mapped==D[converse[i]],"converse intertwines reroot matrix");}for(unsigned k=0;k<components.size();++k){auto c=components[k];unsigned mate=component[converse[c[0]]];for(auto j:c)need(component[converse[j]]==int(mate),"converse respects components");need(grouporders[mate]==grouporders[k],"converse preserves full group order");if(mate==k){++selfchildren;++self_error_hist[K*(c.size()-1)];}}
 ofstream at(prefix+"-parents.txt");at<<atlas.size()<<'\n';for(auto a:atlas){for(auto r:a.r)at<<r<<' ';at<<a.g.size()<<'\n';for(auto g:a.g){for(unsigned j=0;j<N;++j){if(j)at<<' ';at<<g[j];}at<<'\n';}}
 ofstream st(prefix+"-states.tsv");st<<"state\tcomponent\tparent_aut_order\tpointed_source_states\tconverse_state\treroot_destinations\n";for(unsigned i=0;i<atlas.size();++i){st<<i<<'\t'<<component[i]<<'\t'<<atlas[i].g.size()<<'\t'<<atlas[i].pointed_sources<<'\t'<<converse[i]<<'\t';bool first=true;for(auto x:D[i]){if(!first)st<<',';first=false;st<<x.first<<':'<<x.second;}st<<'\n';}
 ofstream cp(prefix+"-components.tsv");cp<<"component\taut_order\terror\tconverse_component\tstates\troot_orbit_sizes\n";for(unsigned k=0;k<components.size();++k){auto c=components[k];cp<<k<<'\t'<<grouporders[k]<<'\t'<<K*(c.size()-1)<<'\t'<<component[converse[c[0]]]<<'\t';for(unsigned j=0;j<c.size();++j){if(j)cp<<',';cp<<c[j];}cp<<'\t';vector<unsigned>orb;for(auto x:D[c[0]])orb.push_back(x.second);sort(orb.begin(),orb.end());for(unsigned j=0;j<orb.size();++j){if(j)cp<<',';cp<<orb[j];}cp<<'\n';}
 ofstream out(prefix+".json");out<<"{\n\"status\":\"PASS\",\n\"source_order\":"<<M<<",\n\"parent_order\":"<<N<<",\n\"regular_order\":"<<K<<",\n\"input_parents\":"<<count<<",\n\"input_labelled_mass\":"<<inputmass<<",\n\"eligible_source_parents\":"<<eligibleparents<<",\n\"eligible_labeled_masks\":"<<rawmasks<<",\n\"eligible_pointed_parent_states\":"<<pointed<<",\n\"almost_regular_parent_classes\":"<<atlas.size()<<",\n\"regular_trace\":"<<trace<<",\n\"regular_classes\":"<<components.size()<<",\n\"regular_error\":"<<totalerror<<",\n\"labelled_almost_regular_mass\":"<<atlas_mass<<",\n\"labelled_regular_mass\":"<<child_mass<<",\n\"self_converse_parents\":"<<selfparents<<",\n\"self_converse_regular_classes\":"<<selfchildren<<",\n\"parent_automorphism_histogram\":";hist(out,aut_hist);out<<",\n\"regular_automorphism_histogram\":";hist(out,child_aut_hist);out<<",\n\"regular_error_histogram\":";hist(out,error_hist);out<<",\n\"self_converse_regular_error_histogram\":";hist(out,self_error_hist);out<<",\n\"generation_rotation_histogram\":";hist(out,rot_hist);out<<",\n\"reroot_rotation_histogram\":";hist(out,trace_rot_hist);out<<",\n\"root_orbit_size_histogram\":[";bool first=true;for(auto x:orbit_hist){if(!first)out<<',';first=false;out<<"[[";for(unsigned i=0;i<x.first.size();++i){if(i)out<<',';out<<x.first[i];}out<<"],"<<x.second<<']';}out<<"],\n\"parent_normalizations\":"<<canonical_calls<<",\n\"full_matrix_candidates\":"<<candidates<<",\n\"refinements\":"<<refinements<<",\n\"checks\":"<<checks<<",\n\"target_canonicalizations\":0\n}\n";need(bool(at)&&bool(st)&&bool(cp)&&bool(out),"all outputs written");cout<<"regular order="<<K<<" M="<<atlas.size()<<" trace="<<trace<<" classes="<<components.size()<<" error="<<totalerror<<" mass="<<atlas_mass<<"\n";
}
int main(int argc,char**argv){try{need(argc==4||argc==5,"usage: regular_trace source_order input prefix [cost]");int m=stoi(argv[1]);bool cost=argc==5;if(m==5)run<5>(argv[2],argv[3],cost);else if(m==7)run<7>(argv[2],argv[3],cost);else if(m==9)run<9>(argv[2],argv[3],cost);else throw runtime_error("source order must be five seven nine");}catch(exception&e){cerr<<e.what()<<'\n';return 1;}}
